private double routeRisk(Point2D.Double goal, List<Wave> threats) {
    double x = getX(), y = getY(), heading = getHeadingRadians(), velocity = getVelocity();
    boolean[] crossed = new boolean[threats.size()];
    double risk = 0, spatial = 0;
    int samples = 0;
    double[] low = new double[threats.size()], high = new double[threats.size()];
    int[] firstTick = new int[threats.size()];
    java.util.Arrays.fill(low, Double.POSITIVE_INFINITY);
    java.util.Arrays.fill(high, Double.NEGATIVE_INFINITY);
    for (int tick = 1; tick <= 100; tick++) {
        double dist = distance(x, y, goal.x, goal.y);
        double turn = normal(angle(x, y, goal.x, goal.y) - heading);
        int drive = 1;
        if (Math.abs(turn) > Math.PI / 2) { turn = normal(turn + Math.PI); drive = -1; }
        double limit = Rules.getTurnRateRadians(velocity);
        heading = normal(heading + clamp(-limit, turn, limit));
        velocity = nextVelocity(velocity * drive, dist) * drive;
        x += Math.sin(heading) * velocity;
        y += Math.cos(heading) * velocity;
        if (!inside(x, y, 18)) { risk += 15; x = clamp(18, x, width - 18); y = clamp(18, y, height - 18); velocity = 0; }
        for (int j = 0; j < threats.size(); j++) {
            Wave w = threats.get(j);
            if (USE_RECT_SURF) {
                if (!crossed[j]) {
                    double inner = w.radius(getTime() + tick - 1);
                    double[] span = rectangleWaveSpan(w, x, y, inner, inner + w.speed);
                    if (span != null) {
                        low[j] = Math.min(low[j], span[0]);
                        high[j] = Math.max(high[j], span[1]);
                        if (firstTick[j] == 0) firstTick[j] = tick;
                    }
                    double dx = Math.abs(x - w.x) + 18, dy = Math.abs(y - w.y) + 18;
                    if (inner * inner > dx * dx + dy * dy) crossed[j] = true;
                }
            } else if (!crossed[j] && w.radius(getTime() + tick) >= distance(w.x, w.y, x, y) - 18) {
                crossed[j] = true;
                double gf = guessFactor(w, x, y);
                double density = danger(w.owner.brain, w.segment, gf);
                int bin = gfBin(gf);
                double maturity = Math.min(1, (w.owner.brain.surfNet.samples
                        + GENERAL_SURF.samples * 0.15) / 40.0);
                double mix = GENOME[3] * maturity;
                density = density * (1 - mix) + w.neuralDanger[bin] * mix;
                if (w.flatten > 0) density = density * (1 - w.flatten) + w.visitDanger[bin] * w.flatten;
                // Head-on como prior; os impactos reais passam a dominar.
                double prior = 0.12 + 0.38 * Math.exp(-gf * gf * 9);
                double learned = Math.min(0.88, w.owner.brain.surfSamples / 12.0);
                double value = USE_CONTEXT_SURF
                        ? w.routePrefix[bin + 1] - w.routePrefix[bin]
                        : prior * (1 - learned) + density * learned * 5;
                risk += value
                        * Rules.getBulletDamage(w.power) * w.confidence * GENOME[0] / (1 + tick * 0.025);
            }
        }
        if (tick % 10 == 0) {
            spatial += positionRisk(x, y, heading, tick);
            samples++;
        }
    }
    if (USE_RECT_SURF) for (int j = 0; j < threats.size(); j++) {
        if (firstTick[j] == 0) continue;
        Wave w = threats.get(j);
        risk += intervalDensity(w.routePrefix, low[j], high[j])
                * Rules.getBulletDamage(w.power) * w.confidence * GENOME[0]
                / (1 + firstTick[j] * 0.025);
    }
    risk += spatial / Math.max(1, samples);
    if (lastDestination != null) risk += 0.08 * Math.exp(-goal.distanceSq(lastDestination) / 10000);
    // Desempate favorece movimento, mas nao proibe a frenagem durante uma onda.
    risk += 0.12 / (1 + distance(getX(), getY(), goal.x, goal.y) / 40);
    return risk;
}

// Densidade por onda calculada uma vez por plano, antes de simular as rotas.
private double[] routeDistribution(Wave w) {
    Brain b = w.owner.brain;
    double sum = 0;
    for (int i = 0; i < BINS; i++) sum += b.surf[w.segment][i] + b.surfGlobal[i] * 0.4;
    double[] context = USE_CONTEXT_SURF && b.context.size >= 4 ? b.context.predict(w.features) : null;
    double contextMix = context == null ? 0 : Math.min(0.55, b.context.size / 40.0);
    double maturity = Math.min(1, (b.surfNet.samples + GENERAL_SURF.samples * 0.15) / 40.0);
    double mix = GENOME[3] * maturity, learned = Math.min(0.88, b.surfSamples / 12.0);
    double[] prefix = new double[BINS + 1];
    for (int i = 0; i < BINS; i++) {
        double density = sum < 0.001 ? 1.0 / BINS
                : (b.surf[w.segment][i] + b.surfGlobal[i] * 0.4) / sum;
        density = density * (1 - mix) + w.neuralDanger[i] * mix;
        if (w.flatten > 0) density = density * (1 - w.flatten) + w.visitDanger[i] * w.flatten;
        if (context != null) density = density * (1 - contextMix) + context[i] * contextMix;
        double gf = 2.0 * i / (BINS - 1) - 1;
        double prior = 0.12 + 0.38 * Math.exp(-gf * gf * 9);
        prefix[i + 1] = prefix[i] + prior * (1 - learned) + density * learned * 5;
    }
    return prefix;
}

// Envelope dos angulos onde o anel de bala cruza o retangulo de 36 x 36.
// Unir envelopes de ticks consecutivos e conservador: pode incluir lacunas.
static double[] rectangleWaveSpan(Wave w, double x, double y, double inner, double outer) {
    double dx = Math.abs(x - w.x), dy = Math.abs(y - w.y);
    double nx = Math.max(0, dx - 18), ny = Math.max(0, dy - 18);
    if (outer * outer < nx * nx + ny * ny
            || inner * inner > (dx + 18) * (dx + 18) + (dy + 18) * (dy + 18)) return null;
    if (dx <= 18 && dy <= 18) return new double[]{-1, 1};
    double[] span = {Double.POSITIVE_INFINITY, Double.NEGATIVE_INFINITY};
    double center = angle(w.x, w.y, x, y);
    for (int a = -1; a <= 1; a += 2) for (int b = -1; b <= 1; b += 2) {
        double px = x + a * 18, py = y + b * 18;
        double d2 = (px - w.x) * (px - w.x) + (py - w.y) * (py - w.y);
        if (d2 >= inner * inner - 1e-8 && d2 <= outer * outer + 1e-8)
            includeWavePoint(w, center, px, py, span);
    }
    for (double radius : new double[]{inner, outer}) for (int side = -1; side <= 1; side += 2) {
        double px = x + side * 18, off = px - w.x;
        double square = radius * radius - off * off;
        if (square >= -1e-8) for (int s = -1; s <= 1; s += 2) {
            double py = w.y + s * Math.sqrt(Math.max(0, square));
            if (py >= y - 18 - 1e-8 && py <= y + 18 + 1e-8)
                includeWavePoint(w, center, px, py, span);
        }
        double py = y + side * 18; off = py - w.y;
        square = radius * radius - off * off;
        if (square >= -1e-8) for (int s = -1; s <= 1; s += 2) {
            px = w.x + s * Math.sqrt(Math.max(0, square));
            if (px >= x - 18 - 1e-8 && px <= x + 18 + 1e-8)
                includeWavePoint(w, center, px, py, span);
        }
    }
    return Double.isFinite(span[0]) ? span : null;
}

private static void includeWavePoint(Wave w, double center, double x, double y, double[] span) {
    double offset = normal(center - w.bearing) + normal(angle(w.x, w.y, x, y) - center);
    double gf = offset * w.direction / Math.asin(8 / w.speed);
    span[0] = Math.min(span[0], gf); span[1] = Math.max(span[1], gf);
}

static double intervalDensity(double[] prefix, double low, double high) {
    low = clamp(-1, low, 1); high = clamp(-1, high, 1);
    if (high - low < 1e-9) return prefix[gfBin(low) + 1] - prefix[gfBin(low)];
    double a = (low + 1) * (BINS - 1) / 2 + 0.5;
    double b = (high + 1) * (BINS - 1) / 2 + 0.5;
    return (prefixValue(prefix, b) - prefixValue(prefix, a)) / (b - a);
}

private static double prefixValue(double[] prefix, double index) {
    int bin = Math.min(BINS - 1, (int) index);
    return prefix[bin] + (prefix[bin + 1] - prefix[bin]) * (index - bin);
}

// KNN limitado por adversario. Aprende angulos observados, nao o codigo inimigo.
static class SurfContext {
    static final int CAPACITY = 192;
    static final double[] WEIGHTS = {2, 5, 1, 1, 0.4, 0.5, 1.5, 1.5, 1, 2, 0.1, 1};
    final double[][] inputs = new double[CAPACITY][];
    final double[] factors = new double[CAPACITY];
    final long[] stamps = new long[CAPACITY];
    int size;
    long seen;
    void observe(double[] input, double factor) {
        int slot = (int) (seen % CAPACITY);
        inputs[slot] = input.clone(); factors[slot] = clamp(-1, factor, 1); stamps[slot] = seen++;
        size = Math.min(CAPACITY, size + 1);
    }
    double[] predict(double[] input) {
        int k = Math.min(size, Math.max(3, (int) Math.sqrt(size)));
        int[] neighbors = new int[k];
        double[] distances = new double[k];
        java.util.Arrays.fill(distances, Double.POSITIVE_INFINITY);
        for (int i = 0; i < size; i++) {
            double distance = 0;
            for (int j = 0; j < WEIGHTS.length; j++) {
                double d = inputs[i][j] - input[j]; distance += d * d * WEIGHTS[j];
            }
            for (int j = 0; j < k; j++) if (distance < distances[j]) {
                for (int n = k - 1; n > j; n--) {distances[n] = distances[n - 1]; neighbors[n] = neighbors[n - 1];}
                distances[j] = distance; neighbors[j] = i; break;
            }
        }
        double[] density = new double[BINS];
        java.util.Arrays.fill(density, 0.001);
        for (int n = 0; n < k; n++) {
            int i = neighbors[n];
            double weight = Math.pow(0.99, seen - 1 - stamps[i]) / (0.05 + distances[n]);
            for (int b = 0; b < BINS; b++) {
                double delta = (2.0 * b / (BINS - 1) - 1 - factors[i]) / 0.12;
                density[b] += weight / (1 + delta * delta);
            }
        }
        double sum = 0; for (double d : density) sum += d;
        for (int i = 0; i < BINS; i++) density[i] /= sum;
        return density;
    }
}
